func (s *Service) NewPayload(ctx, payload, versionedHashes, parentBlockRoot, executionRequests) ([]byte, error) {
    // dispatches to engine_newPayloadV1/V2/V3/V4 based on payload type
    // V4 for Electra (includes executionRequests for system contracts)
    case *pb.ExecutionPayloadDeneb:
        if executionRequests != nil {
            flattenedRequests, err := pb.EncodeExecutionRequests(executionRequests)
            err = s.rpcClient.CallContext(ctx, result, NewPayloadMethodV4, payloadPb, versionedHashes, parentBlockRoot, flattenedRequests)
        }
    // Result handling: EL validates system contracts have code
    switch result.Status {
    case pb.PayloadStatus_INVALID_BLOCK_HASH: return nil, ErrInvalidBlockHashPayloadStatus
    case pb.PayloadStatus_INVALID: return result.LatestValidHash, ErrInvalidPayloadStatus
    case pb.PayloadStatus_VALID: return result.LatestValidHash, nil
    }
}

// execution_engine.go: notifyNewPayload error handling
lastValidHash, err = s.cfg.ExecutionEngineCaller.NewPayload(ctx, payload, versionedHashes, parentRoot, requests)
switch {
case err == nil:
    return true, nil  // VALID
case errors.Is(err, execution.ErrAcceptedSyncingPayloadStatus):
    return false, nil  // optimistic
case errors.Is(err, execution.ErrInvalidPayloadStatus):
    return false, invalidBlock{error: ErrInvalidPayload, lastValidHash: lvh}  // correctly wrapped as invalidBlock
default:
    // BUG: execution.ErrInvalidBlockHashPayloadStatus falls here!
    return false, errors.WithMessage(ErrUndefinedExecutionEngineError, err.Error())  // NOT invalidBlock
}

