func (s *Service) handleInvalidExecutionError(ctx, err, root, parentRoot) error {
    if IsInvalidBlock(err) && InvalidBlockLVH(err) != [32]byte{} {
        return s.pruneInvalidBlock(ctx, root, parentRoot, InvalidBlockLVH(err))
    }
    // BUG: INVALID_BLOCK_HASH path never calls pruneInvalidBlock because IsInvalidBlock returns false
    return err
}
